1	package org.jsoup.safety;
2	
3	import org.jsoup.internal.Normalizer;
4	import org.jsoup.internal.StringUtil;
5	import org.jsoup.nodes.Attribute;
6	import org.jsoup.nodes.Element;
7	
8	import java.util.ArrayList;
9	import java.util.Collections;
10	import java.util.List;
11	import java.util.Set;
12	
13	/**
14	 Validates and rewrites {@code srcset} attributes, one image candidate at a time.
15	 <p>
16	 The attribute value is split into candidates following the HTML {@code srcset} parsing rules: a candidate consists of a
17	 URL followed by an optional width ({@code w}) or pixel density ({@code x}) descriptor. Commas only separate
18	 candidates at a candidate boundary, so commas nested inside a {@code data:} URL, a quoted value, or entity-decoded
19	 content are preserved. A candidate address may be wrapped in matching {@code "} or {@code '} quotes; the commas and
20	 whitespace inside are literal and the quotes never become part of the address. Each surviving URL is checked
21	 against the safelist with the same protocol and encoding rules used for ordinary URI attributes such as {@code src};
22	 invalid descriptors cause their single candidate to be dropped, without affecting the other candidates.
23	 </p>
24	 */
25	final class SrcsetCleaner {
26	    private SrcsetCleaner() {}
27	
28	    private static final int InDescriptor = 1;
29	    private static final int InParens = 2;
30	    private static final int AfterDescriptor = 3;
31	
32	    /**
33	     Determine whether the supplied attribute is a {@code srcset} attribute that should be handled candidate by
34	     candidate, rather than treated as an ordinary opaque attribute.
35	     @param attr the attribute to test
36	     @return true if it is a {@code srcset} attribute
37	     */
38	    static boolean isSrcset(Attribute attr) {
39	        return "srcset".equalsIgnoreCase(attr.getKey());
40	    }
41	
42	    /**
43	     Clean a {@code srcset} attribute value into a value containing only the acceptable candidates, in their original
44	     order. The input element is not modified; callers must apply the result themselves.
45	     @param el the element carrying the attribute (used for URL resolution against its base URI)
46	     @param rawValue the original attribute value
47	     @param safelist the safelist to validate each candidate URL against
48	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no candidate survived, in
49	     which case the attribute must be removed rather than left empty
50	     */
51	    static Result clean(Element el, String rawValue, Safelist safelist) {
52	        List<Candidate> accepted = new ArrayList<>();
53	        int dropped = 0;
54	        if (rawValue != null && !rawValue.isEmpty()) {
55	            int pos = 0;
56	            int len = rawValue.length();
57	
58	            while (pos < len) {
59	                // 1. Splitting loop: skip a run of ASCII whitespace and candidate-separating commas. Empty items,
60	                //    consecutive commas, and trailing separators are consumed here and never raise an error.
61	                while (pos < len && isWsOrComma(rawValue.charAt(pos))) pos++;
62	                if (pos >= len) break;
63	
64	                // 2. Collect the URL and whatever descriptor tokens follow it. A URL run may be wrapped in matching
65	                //    quotes, in which case its commas and whitespace are literal address content.
66	                UrlRun run = collectUrl(rawValue, pos);
67	                pos = run.nextPos;
68	                if (!run.valid) { // malformed quoted run: drop this item, keep parsing any later candidates
69	                    dropped++;
70	                    continue;
71	                }
72	                String url = run.url;
73	
74	                if (url.isEmpty()) continue;
75	
76	                String descriptor = parseDescriptors(run.descriptors);
77	                String safeUrl = (descriptor != null) ? isSafeUrl(el, url, safelist) : null;
78	                if (safeUrl != null)
79	                    accepted.add(new Candidate(safeUrl, descriptor, run.quoted, run.quoteChar));
80	                else
81	                    dropped++;
82	            }
83	        }
84	
85	        if (accepted.isEmpty()) return new Result(null, dropped, true);
86	        return new Result(serialize(accepted), dropped, false);
87	    }
88	
89	    /** The outcome of cleaning a srcset attribute: the rewritten {@code value} (or null) and statistics. */
90	    static final class Result {
91	        final String value;
92	        final int droppedCandidates;
93	        final boolean removed;
94	
95	        private Result(String value, int droppedCandidates, boolean removed) {
96	            this.value = value;
97	            this.droppedCandidates = droppedCandidates;
98	            this.removed = removed;
99	        }
100	    }
101	
102	    private static final class TokenizerResult {
103	        final List<String> tokens;
104	        final int nextPos; // position just past the candidate-separating comma, or at end of input
105	
106	        private TokenizerResult(List<String> tokens, int nextPos) {
107	            this.tokens = tokens;
108	            this.nextPos = nextPos;
109	        }
110	    }
111	
112	    /** One collected candidate: the decoded URL, its descriptor tokens, and where parsing should continue. */
113	    private static final class UrlRun {
114	        final String url;
115	        final List<String> descriptors;
116	        final int nextPos;
117	        final boolean valid; // false for a malformed quoted run (junk after the quote, or an unterminated quote)
118	        final boolean quoted;
119	        final char quoteChar; // the delimiter when {@code quoted}, otherwise undefined
120	
121	        private UrlRun(String url, List<String> descriptors, int nextPos, boolean valid, boolean quoted, char quoteChar) {
122	            this.url = url;
123	            this.descriptors = descriptors;
124	            this.nextPos = nextPos;
125	            this.valid = valid;
126	            this.quoted = quoted;
127	            this.quoteChar = quoteChar;
128	        }
129	    }
130	
131	    /**
132	     Collect one candidate starting at {@code start}: its URL run and the descriptor tokens that follow it.
133	     <p>
134	     A run whose first character is a matching {@code "} or {@code '} is quoted: the address runs to the closing
135	     delimiter, so embedded commas, whitespace, and decoded character references are literal address content rather
136	     than candidate boundaries. The delimiter itself never becomes part of the address. The closing quote may be
137	     followed by whitespace introducing descriptors, a boundary comma, or end of input; any other character glued
138	     directly to the quote invalidates the candidate. An unterminated quote drops that item, and parsing resyncs at
139	     the next candidate comma so any following valid candidate is still considered.
140	     </p>
141	     */
142	    private static UrlRun collectUrl(String input, int start) {
143	        int len = input.length();
144	        char first = input.charAt(start);
145	
146	        if (first == '"' || first == '\'') {
147	            char quote = first;
148	            int contentStart = start + 1;
149	            int p = contentStart;
150	            while (p < len && input.charAt(p) != quote) p++;
151	            if (p >= len) {
152	                // Unterminated quote: the malformed item is dropped, but a later comma still resyncs parsing so a
153	                // following valid candidate is not swallowed. Without a comma there is nothing more to recover.
154	                int comma = input.indexOf(',', contentStart);
155	                int nextPos = comma >= 0 ? comma + 1 : len;
156	                return new UrlRun(input.substring(contentStart), Collections.emptyList(), nextPos, false, true, quote);
157	            }
158	            String url = input.substring(contentStart, p);
159	            p++; // the closing quote
160	
161	            int q = p;
162	            boolean separated = false;
163	            while (q < len && StringUtil.isWhitespace(input.charAt(q))) { q++; separated = true; }
164	
165	            if (q < len && input.charAt(q) == ',') {
166	                return new UrlRun(url, Collections.emptyList(), q + 1, true, true, quote);
167	            }
168	            if (q == len) {
169	                return new UrlRun(url, Collections.emptyList(), q, true, true, quote);
170	            }
171	            // Descriptor tokens begin here; they are legal only after whitespace separating them from the quote.
172	            // Tokenize regardless so that the boundary comma (if any) is consumed and later candidates survive.
173	            TokenizerResult tokenized = tokenizeDescriptors(input, q);
174	            return new UrlRun(url, tokenized.tokens, tokenized.nextPos, separated, true, quote);
175	        }
176	
177	        // Unquoted URL: a run of non-whitespace characters.
178	        int urlStart = start;
179	        int pos = start;
180	        while (pos < len && !StringUtil.isWhitespace(input.charAt(pos))) pos++;
181	        int urlRunEnd = pos;
182	        int urlEnd = urlRunEnd;
183	        while (urlEnd > urlStart && input.charAt(urlEnd - 1) == ',') urlEnd--;
184	        String url = input.substring(urlStart, urlEnd);
185	
186	        if (urlEnd < urlRunEnd) {
187	            // The URL run ended in comma(s) with no whitespace: the boundary has no descriptor and parsing restarts
188	            // at the splitting loop. This is what keeps a comma inside a data: URL (e.g. "data:,Hello") in the URL.
189	            return new UrlRun(url, Collections.emptyList(), urlRunEnd, true, false, (char) 0);
190	        }
191	        // Tokenize the descriptors with the HTML srcset state machine, so that a comma nested in a parenthesized
192	        // (or quoted) descriptor does not get mistaken for a candidate boundary.
193	        TokenizerResult tokenized = tokenizeDescriptors(input, pos);
194	        return new UrlRun(url, tokenized.tokens, tokenized.nextPos, true, false, (char) 0);
195	    }
196	
197	    private static boolean isWsOrComma(char c) {
198	        return c == ',' || StringUtil.isWhitespace(c);
199	    }
200	
201	    /**
202	     Run the HTML srcset descriptor tokenizer starting at the first character after the URL's whitespace run.
203	     Parenthesized content (and anything quoted within it) is taken verbatim, so commas and whitespace inside it
204	     cannot start a new candidate. Stops at a boundary comma (consumed) or end of input.
205	     */
206	    private static TokenizerResult tokenizeDescriptors(String input, int pos) {
207	        List<String> tokens = new ArrayList<>();
208	        int len = input.length();
209	        int state = InDescriptor;
210	        StringBuilder token = new StringBuilder();
211	
212	        while (pos < len) {
213	            char c = input.charAt(pos);
214	            switch (state) {
215	                case InDescriptor:
216	                    if (StringUtil.isWhitespace(c)) {
217	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
218	                        state = AfterDescriptor;
219	                    } else if (c == ',') {
220	                        if (token.length() > 0) { tokens.add(token.toString()); token.setLength(0); }
221	                        return new TokenizerResult(tokens, pos + 1); // consume the candidate separator
222	                    } else if (c == '(') {
223	                        token.append(c);
224	                        state = InParens;
225	                    } else {
226	                        token.append(c);
227	                    }
228	                    pos++;
229	                    break;
230	                case InParens:
231	                    token.append(c); // commas, whitespace, and quotes in here are all literal
232	                    if (c == ')') state = InDescriptor;
233	                    pos++;
234	                    break;
235	                case AfterDescriptor:
236	                    if (StringUtil.isWhitespace(c)) {
237	                        pos++;
238	                    } else if (c == ',') {
239	                        return new TokenizerResult(tokens, pos + 1);
240	                    } else {
241	                        state = InDescriptor; // reprocess this character as a new token
242	                    }
243	                    break;
244	            }
245	        }
246	        if (token.length() > 0) tokens.add(token.toString());
247	        return new TokenizerResult(tokens, pos);
248	    }
249	
250	    /**
251	     Validate the tokenized descriptor list of one candidate. Legal forms are: no descriptor, a single non-zero
252	     width ({@code <integer>w}), or a single finite strictly-positive pixel density ({@code <number>x}). Duplicated,
253	     unknown, parenthesized, or syntactically invalid descriptors invalidate the candidate.
254	     @return the normalized descriptor suffix ({@code ""} when absent, or {@code " <descriptor>"}), or {@code null}
255	     */
256	    private static String parseDescriptors(List<String> tokens) {
257	        if (tokens.isEmpty()) return "";
258	        if (tokens.size() > 1) return null;
259	
260	        String descriptor = tokens.get(0);
261	        if (descriptor.isEmpty()) return "";
262	        char suffix = descriptor.charAt(descriptor.length() - 1);
263	        if (suffix != 'w' && suffix != 'x') return null; // only lower-case width/density descriptors are valid
264	        String number = descriptor.substring(0, descriptor.length() - 1);
265	        if (number.isEmpty()) return null;
266	
267	        if (suffix == 'w') {
268	            if (parseWidth(number) == null) return null;
269	        } else {
270	            if (parseDensity(number) == null) return null;
271	        }
272	        return " " + descriptor;
273	    }
274	
275	    /** Parse a non-negative integer with no sign, exponent, or decimal point; zero and overflow are invalid. */
276	    private static Long parseWidth(String s) {
277	        long value = 0;
278	        for (int i = 0; i < s.length(); i++) {
279	            char c = s.charAt(i);
280	            if (c < '0' || c > '9') return null;
281	            int digit = c - '0';
282	            if (value > (Long.MAX_VALUE - digit) / 10) return null; // overflow
283	            value = value * 10 + digit;
284	        }
285	        return value == 0L ? null : value;
286	    }
287	
288	    /** Parse a finite strictly-positive floating-point number matching the HTML valid floating-point number grammar. */
289	    private static Double parseDensity(String s) {
290	        int i = 0;
291	        if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
292	            if (s.charAt(i) == '-') return null;
293	            i++;
294	        }
295	        int intDigits = 0;
296	        while (i < s.length() && isAsciiDigit(s.charAt(i))) { intDigits++; i++; }
297	        int fracDigits = 0;
298	        if (i < s.length() && s.charAt(i) == '.') {
299	            i++;
300	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { fracDigits++; i++; }
301	        }
302	        // grammar: digits before the optional dot, or digits after it (".5"); a lone "." is invalid
303	        if (intDigits == 0 && fracDigits == 0) return null;
304	        if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
305	            i++;
306	            if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
307	            int exponentDigits = 0;
308	            while (i < s.length() && isAsciiDigit(s.charAt(i))) { exponentDigits++; i++; }
309	            if (exponentDigits == 0) return null;
310	        }
311	        if (i != s.length()) return null; // trailing junk
312	        try {
313	            double value = Double.parseDouble(s);
314	            // the descriptor must be a strictly positive finite number: zero, negatives, NaN, and infinity are invalid
315	            if (!(value > 0d) || Double.isNaN(value) || Double.isInfinite(value)) return null;
316	            return value;
317	        } catch (NumberFormatException e) {
318	            return null;
319	        }
320	    }
321	
322	    private static boolean isAsciiDigit(char c) {
323	        return c >= '0' && c <= '9';
324	    }
325	
326	    /**
327	     Check one candidate URL against the safelist's protocol policy and return the URL spelling to emit.
328	     <p>
329	     Character references have already been decoded by the parser, so a URL that still contains an ASCII control
330	     character or newline is rejected outright: such characters cannot occur in a conforming address and are used to
331	     smuggle disguised {@code javascript:} or {@code data:} schemes past a prefix test. Other URLs are resolved and
332	     checked exactly like an ordinary URI attribute such as {@code src}. When relative links are not preserved,
333	     resolvable candidates are emitted in absolute form.
334	     </p>
335	     @return the URL to keep (absolute or original spelling), or {@code null} if it must be dropped
336	     */
337	    private static String isSafeUrl(Element el, String url, Safelist safelist) {
338	        if (containsControlChar(url)) return null; // controls, tabs, and newlines can never be part of a safe address
339	
340	        Set<Safelist.Protocol> protocols = safelist.srcsetProtocols(el.normalName());
341	        if (protocols.isEmpty()) return url; // no protocol policy: accept, like an ordinary untyped attribute
342	
343	        String resolved = StringUtil.resolve(el.baseUri(), url);
344	        String check = resolved;
345	        if (check.isEmpty() && !StringUtil.hasHttpScheme(url)) check = url; // custom schemes checked as written
346	        if (check.isEmpty()) return null; // an unresolvable relative URL with no base is not acceptable
347	
348	        String lc = Normalizer.lowerCase(check);
349	        for (Safelist.Protocol protocol : protocols) {
350	            String prot = protocol.toString();
351	            if (prot.equals("#")) continue; // fragment anchors are not image candidates
352	            if (lc.startsWith(prot)
353	                && lc.length() > prot.length()
354	                && lc.charAt(prot.length()) == ':') {
355	                // Emit the absolute form like an ordinary src value, unless relative links are preserved.
356	                return (!safelist.preserveRelativeLinks() && !resolved.isEmpty()) ? resolved : url;
357	            }
358	        }
359	        return null;
360	    }
361	
362	    private static boolean containsControlChar(String url) {
363	        for (int i = 0; i < url.length(); i++) {
364	            char c = url.charAt(i);
365	            if (c <= 0x1f || c == 0x7f) return true;
366	        }
367	        return false;
368	    }
369	
370	    private static String serialize(List<Candidate> candidates) {
371	        StringBuilder sb = StringUtil.borrowBuilder();
372	        for (int i = 0; i < candidates.size(); i++) {
373	            if (i > 0) sb.append(", ");
374	            Candidate candidate = candidates.get(i);
375	            // A quoted address is re-wrapped in its original delimiter so the serialized value parses back into the
376	            // same single candidate (its inner commas/whitespace stay literal). Unquoted runs never contain
377	            // whitespace, so they need no wrapping.
378	            if (candidate.quoted) sb.append(candidate.quoteChar);
379	            sb.append(candidate.url);
380	            if (candidate.quoted) sb.append(candidate.quoteChar);
381	            sb.append(candidate.descriptor);
382	        }
383	        return StringUtil.releaseBuilder(sb);
384	    }
385	
386	    private static final class Candidate {
387	        final String url;
388	        final String descriptor; // normalized as "" or " <descriptor>"
389	        final boolean quoted;
390	        final char quoteChar;
391	
392	        Candidate(String url, String descriptor, boolean quoted, char quoteChar) {
393	            this.url = url;
394	            this.descriptor = descriptor;
395	            this.quoted = quoted;
396	            this.quoteChar = quoteChar;
397	        }
398	    }
399	}
