3	import org.jsoup.Jsoup;
4	import org.jsoup.nodes.Document;
5	import org.jsoup.nodes.Element;
6	import org.junit.jupiter.api.Test;
7	
8	import static org.junit.jupiter.api.Assertions.*;
9	
10	/**
11	 Tests for per-candidate cleaning of {@code srcset} attributes in the {@link Cleaner}.
12	 */
13	public class SrcsetCleanerTest {
14	
15	    private static Safelist safelist() {
16	        return Safelist.relaxed().addAttributes("img", "srcset");
17	    }
18	
19	    @Test void srcsetRemovedWhenNotAllowed() {
20	        // without the attribute in the safelist, the existing attribute-removal behavior is unchanged
21	        String html = "<img src=\"http://example.com/src.jpg\" srcset=\"http://example.com/a.jpg 1x\">";
22	        String clean = Jsoup.clean(html, Safelist.relaxed());
23	        assertEquals("<img src=\"http://example.com/src.jpg\">", clean);
24	    }
25	
26	    @Test void retainsCandidatesAndDescriptors() {
27	        String html = "<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x, http://example.com/c.jpg 300w\">";
28	        String clean = Jsoup.clean(html, safelist());
29	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x, http://example.com/c.jpg 300w\">", clean);
30	    }
31	
32	    @Test void retainsCandidateWithoutDescriptor() {
33	        String clean = Jsoup.clean("<img srcset=\"http://example.com/a.jpg, http://example.com/b.jpg 2x\">", safelist());
34	        assertEquals("<img srcset=\"http://example.com/a.jpg, http://example.com/b.jpg 2x\">", clean);
35	    }
36	
37	    @Test void normalizesWhitespaceAroundDescriptors() {
38	        String clean = Jsoup.clean("<img srcset=\"  http://example.com/a.jpg     1x  , http://example.com/b.jpg  2x \">", safelist());
39	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
40	    }
41	
42	    @Test void resolvesRelativeCandidatesAgainstBaseUri() {
43	        String html = "<img srcset=\"/a.jpg 1x, /b.jpg 2x\">";
44	        String clean = Jsoup.clean(html, "http://example.com/path/", safelist());
45	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
46	    }
47	
48	    @Test void preservesRelativeCandidatesWhenConfigured() {
49	        Safelist safelist = safelist().preserveRelativeLinks(true);
50	        String clean = Jsoup.clean("<img srcset=\"/a.jpg 1x, http://example.com/b.jpg 2x\">", "http://example.com/", safelist);
51	        assertEquals("<img srcset=\"/a.jpg 1x, http://example.com/b.jpg 2x\">", clean);
52	    }
53	
54	    @Test void dropsUnresolvableRelativeCandidatesWithoutBase() {
55	        String clean = Jsoup.clean("<img srcset=\"/a.jpg 1x\">", safelist());
56	        assertEquals("<img>", clean);
57	    }
58	
59	    @Test void dropsJavascriptCandidateAndKeepsRest() {
60	        String html = "<img srcset=\"javascript:alert(1) 1x, http://example.com/a.jpg 1x\">";
61	        String clean = Jsoup.clean(html, safelist());
62	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
63	    }
64	
65	    @Test void dropsDisguisedJavascriptCandidate() {
66	        // entity-decoded tabs/newlines/control characters must not smuggle a scheme through
67	        String html = "<img srcset=\"&#0013;ja&Tab;va&Tab;script&#0010;:alert(1) 1x, http://example.com/a.jpg 1x\">";
68	        String clean = Jsoup.clean(html, "https://", safelist());
69	        assertEquals("<img srcset=\"http://example.com/a.jpg 1x\">", clean);
