244	        String clean = Jsoup.clean("<source srcset=\"http://example.com/a.jpg 1x, javascript:x 2x\">", "http://example.com/", safelist);
245	        assertEquals("<source srcset=\"http://example.com/a.jpg 1x\">", clean);
246	    }
