273	        assertEquals("<img><img srcset=\"http://example.com/ok.jpg 1x\">", clean.body().html());
274	    }
275	
276	    @Test void inputDocumentIsNotModified() {
277	        Document dirty = Jsoup.parseBodyFragment(
278	            "<img srcset=\"/a.jpg 1x, javascript:bad 2x\">", "http://example.com/");
279	        Element img = dirty.expectFirst("img");
