285	
286	    @Test void cleaningIsIdempotentAndReparseable() {
287	        String html = "<img srcset=\"  /a.jpg     1x ,  http://example.com/b.jpg  2x , javascript:bad 3x\">";
288	        Cleaner cleaner = new Cleaner(safelist());
