329	        // the comma inside the (invalid, image-relevant) descriptor is not a candidate boundary; it is dropped alone
330	        String html = "<img srcset=\"http://example.com/a.jpg (min-width: 400px, foo: bar), http://example.com/b.jpg 1x\">";
331	        String clean = Jsoup.clean(html, safelist());
332	        assertEquals("<img srcset=\"http://example.com/b.jpg 1x\">", clean);
333	    }
