336	        String html = "<img srcset=\"http://example.com/ok.jpg 1x, ja&Tab;vas&#x09;cript:alert(1) 2x\">";
337	        String clean = Jsoup.clean(html, "https://", safelist());
338	        assertEquals("<img srcset=\"http://example.com/ok.jpg 1x\">", clean);
339	    }
