341	    @Test void leadingControlCharsDoNotBypassSchemeCheck() {
342	        String html = "<img srcset=\"&#01;&#10;javascript:alert(1), http://example.com/ok.jpg 1x\">";
343	        String clean = Jsoup.clean(html, "https://", safelist());
