import org.jsoup.Jsoup;
import org.jsoup.safety.Safelist;

public class WidthProbe {
    public static void main(String[] args) {
        Safelist sl = Safelist.relaxed().addAttributes("img", "srcset");
        String[] cases = {
            "http://e/x.jpg 5w",        // valid
            "http://e/x.jpg 0w",        // zero -> drop
            "http://e/x.jpg 000w",      // zero with leading zeros -> drop
            "http://e/x.jpg 007w",      // leading zeros, positive -> keep
            "http://e/x.jpg +5w",       // sign -> drop
            "http://e/x.jpg -5w",       // sign -> drop
            "http://e/x.jpg 1.5w",      // decimal -> drop
            "http://e/x.jpg 5w 10w",    // duplicate width -> drop
            "http://e/x.jpg 5w 2x",     // mixed descriptors -> drop
            "http://e/x.jpg 5W",        // uppercase -> drop
            "http://e/x.jpg w",         // no digits -> drop
            "http://e/x.jpg 5ww",       // junk -> drop
            "http://e/x.jpg 99999999999999999999w", // overflow -> drop
            "http://e/x.jpg 5w,",       // trailing comma ok
        };
        for (String c : cases) {
            String out = Jsoup.clean("<img srcset=\"" + c + "\">", "http://e/", sl);
            System.out.println(String.format("%-45s -> %s", c, out));
        }
    }
}
